-- Extensión documental independiente de custodia/firmas/COM/ACK. V1–V9 permanecen intactas.
ALTER TABLE core_action ADD CONSTRAINT uq_action_case UNIQUE(id,case_id);
CREATE TABLE management_document_link(document_id VARCHAR(36) NOT NULL,case_id VARCHAR(36) NOT NULL,action_id VARCHAR(36),context_id VARCHAR(36) NOT NULL,linked_by VARCHAR(64) NOT NULL,linked_ms BIGINT NOT NULL,PRIMARY KEY(document_id,case_id,context_id),FOREIGN KEY(document_id) REFERENCES institution_document(id),FOREIGN KEY(case_id) REFERENCES core_case(id),FOREIGN KEY(action_id,case_id) REFERENCES core_action(id,case_id),FOREIGN KEY(linked_by) REFERENCES core_actor(id),CHECK((action_id IS NULL AND context_id='CASO') OR (action_id IS NOT NULL AND context_id=action_id)));
CREATE TABLE document_command(id VARCHAR(36) PRIMARY KEY,actor_id VARCHAR(64) NOT NULL,case_id VARCHAR(36) NOT NULL,operation_code VARCHAR(24) NOT NULL,request_hash CHAR(64) NOT NULL,document_id VARCHAR(36) NOT NULL,created_ms BIGINT NOT NULL,FOREIGN KEY(actor_id) REFERENCES core_actor(id),FOREIGN KEY(case_id) REFERENCES core_case(id),FOREIGN KEY(document_id) REFERENCES institution_document(id));
CREATE TABLE document_representation(document_id VARCHAR(36) NOT NULL,profile VARCHAR(40) NOT NULL,source_sha256 CHAR(64) NOT NULL,pages INT NOT NULL,created_ms BIGINT NOT NULL,PRIMARY KEY(document_id,profile),FOREIGN KEY(document_id) REFERENCES institution_document(id),CHECK(pages BETWEEN 1 AND 100));
CREATE TABLE document_page(document_id VARCHAR(36) NOT NULL,profile VARCHAR(40) NOT NULL,page_number INT NOT NULL,size_bytes BIGINT NOT NULL,sha256 CHAR(64) NOT NULL,storage_key VARCHAR(200) NOT NULL,created_ms BIGINT NOT NULL,PRIMARY KEY(document_id,profile,page_number),FOREIGN KEY(document_id,profile) REFERENCES document_representation(document_id,profile),CHECK(page_number BETWEEN 1 AND 100),CHECK(size_bytes BETWEEN 1 AND 6291456));
CREATE TABLE document_event(seq BIGINT AUTO_INCREMENT PRIMARY KEY,document_id VARCHAR(36),case_id VARCHAR(36),action_id VARCHAR(36),actor_id VARCHAR(64) NOT NULL,at_ms BIGINT NOT NULL,event_code VARCHAR(40) NOT NULL,FOREIGN KEY(document_id) REFERENCES institution_document(id),FOREIGN KEY(case_id) REFERENCES core_case(id),FOREIGN KEY(action_id) REFERENCES core_action(id),FOREIGN KEY(actor_id) REFERENCES core_actor(id));
CREATE INDEX ix_management_case ON management_document_link(case_id,document_id);
CREATE INDEX ix_document_event ON document_event(document_id,seq);
